import { siteConfig } from '../data/siteConfig.js';
import { sectionLabel, arrow } from './shared.js';
import { socialIcon } from './socialIcons.js';
export function Contact() { return `<section id="contact" class="contact section" aria-labelledby="contact-title"><div class="contact-earth" aria-hidden="true"></div><div class="container">${sectionLabel('06','CONTACT')}<div class="contact-content"><span class="eyebrow reveal">BACK TO THE HORIZON. OPEN TO WHAT’S NEXT.</span><h2 id="contact-title" class="reveal">Let’s build something<br><span class="soft-text">meaningful.</span></h2><p class="reveal">Have an idea? Let’s make it real.</p><div class="contact-links reveal" aria-label="YouTube、X、GitHub 与 Email">${siteConfig.contact.map(c=>`<a class="social-link" href="${c.href}" title="${c.note}" ${c.label==='Email'?'':'target="_blank" rel="noopener noreferrer"'}>${socialIcon(c.label)}<span>${c.label}</span>${arrow}</a>`).join('')}</div><p class="small-note reveal">YouTube 暂时跳转官网。</p></div></div></section>`; }
